const ticket = new Promise((resolve, reject) => {
  setTimeout(() => reject(new Error("sold out")), 10);
  resolve("seat 4");
});

ticket.then(
  (seat) => console.log("booked " + seat),
  (error) => console.log("failed: " + error.message)
);
ticket.finally(() => console.log("closed"));
console.log("checking");
